          "id": "code-ml-24-2-ch24_2_scratch",
          "title": "First-Principles NumPy: Standard Isolation Forest vs Extended IF (Oblique) pada Ghost Regions",
          "language": "python",
          "filename": "24_2_iforest_vs_extended_if_scratch.py",
          "code": "import numpy as np\nfrom sklearn.metrics import average_precision_score, roc_auc_score\n\nrng = np.random.default_rng(2421)\n\nEULER_GAMMA = 0.5772156649015329\n\ndef c_factor(n: int) -> float:\n    \"\"\"Rata-rata panjang lintasan pencarian gagal pada BST berukuran n (Liu et al. 2008).\"\"\"\n    if n <= 1:\n        return 0.0\n    if n == 2:\n        return 1.0\n    h_n_minus_1 = np.log(n - 1.0) + EULER_GAMMA\n    return float(2.0 * h_n_minus_1 - (2.0 * (n - 1.0) / n))\n\ndef build_itree(X: np.ndarray, depth: int, max_depth: int, oblique: bool, rng_local: np.random.Generator) -> dict:\n    n, d = X.shape\n    if depth >= max_depth or n <= 1:\n        return {\"leaf\": True, \"size\": n}\n    mins = np.min(X, axis=0)\n    maxs = np.max(X, axis=0)\n    if np.allclose(mins, maxs):\n        return {\"leaf\": True, \"size\": n}\n\n    if not oblique:\n        # Standard Isolation Forest: pemotongan sejajar sumbu (axis-aligned)\n        q = int(rng_local.integers(0, d))\n        if mins[q] == maxs[q]:\n            return {\"leaf\": True, \"size\": n}\n        p = float(rng_local.uniform(mins[q], maxs[q]))\n        mask_left = X[:, q] < p\n        return {\n            \"leaf\": False, \"oblique\": False, \"q\": q, \"p\": p,\n            \"left\": build_itree(X[mask_left], depth + 1, max_depth, False, rng_local),\n            \"right\": build_itree(X[~mask_left], depth + 1, max_depth, False, rng_local),\n        }\n    else:\n        # Extended Isolation Forest (Hariri et al. 2019): hyperplane miring acak (x - p) . n <= 0\n        normal = rng_local.standard_normal(d)\n        intercept = rng_local.uniform(mins, maxs)\n        mask_left = ((X - intercept) @ normal) <= 0.0\n        if np.all(mask_left) or not np.any(mask_left):\n            return {\"leaf\": True, \"size\": n}\n        return {\n            \"leaf\": False, \"oblique\": True, \"normal\": normal, \"intercept\": intercept,\n            \"left\": build_itree(X[mask_left], depth + 1, max_depth, True, rng_local),\n            \"right\": build_itree(X[~mask_left], depth + 1, max_depth, True, rng_local),\n        }\n\ndef path_length(node: dict, x: np.ndarray, depth: int = 0) -> float:\n    if node[\"leaf\"]:\n        return float(depth) + c_factor(node[\"size\"])\n    if not node[\"oblique\"]:\n        go_left = x[node[\"q\"]] < node[\"p\"]\n    else:\n        go_left = float(np.dot(x - node[\"intercept\"], node[\"normal\"])) <= 0.0\n    return path_length(node[\"left\"] if go_left else node[\"right\"], x, depth + 1)\n\ndef score_forest(X_train: np.ndarray, X_eval: np.ndarray, n_trees: int, psi: int, oblique: bool, seed: int) -> tuple[np.ndarray, np.ndarray]:\n    rng_f = np.random.default_rng(seed)\n    max_depth = int(np.ceil(np.log2(psi)))\n    n = X_train.shape[0]\n    trees = []\n    for _ in range(n_trees):\n        idx = rng_f.choice(n, size=min(psi, n), replace=False)\n        trees.append(build_itree(X_train[idx], 0, max_depth, oblique, rng_f))\n    c_psi = c_factor(min(psi, n))\n    mean_h = np.zeros(X_eval.shape[0], dtype=float)\n    for t in trees:\n        for i in range(X_eval.shape[0]):\n            mean_h[i] += path_length(t, X_eval[i], 0)\n    mean_h /= n_trees\n    scores = np.power(2.0, -mean_h / c_psi)\n    return scores, mean_h\n\n# Dataset uji klasik \"Ghost Regions\" (Hariri et al. 2019):\n# Dua klaster normal diagonal di Kuadran I [3.5, 3.5] & Kuadran III [-3.5, -3.5]\n# Anomali ditempatkan tepat di GHOST REGIONS Kuadran II [-3.5, 3.5] & Kuadran IV [3.5, -3.5]\n# (secara koordinat x1 dan x2 masing-masing berada persis di dalam rentang klaster normal!)\nX_norm = np.vstack([\n    rng.normal([3.5, 3.5], 0.55, size=(180, 2)),\n    rng.normal([-3.5, -3.5], 0.55, size=(180, 2)),\n])\nX_ghost_anom = np.vstack([\n    rng.normal([-3.5, 3.5], 0.35, size=(16, 2)),\n    rng.normal([3.5, -3.5], 0.35, size=(16, 2)),\n])\nX_all = np.vstack([X_norm, X_ghost_anom])\ny_all = np.array([0] * 360 + [1] * 32)\n\ns_std, h_std = score_forest(X_norm, X_all, n_trees=60, psi=128, oblique=False, seed=42)\ns_eif, h_eif = score_forest(X_norm, X_all, n_trees=60, psi=128, oblique=True, seed=42)\n\nprint(f\"=== 1. Verifikasi Konstanta BST c(psi) Liu et al. (2008) ===\")\nprint(f\"c(64) = {c_factor(64):.4f} | c(128) = {c_factor(128):.4f} | c(256) = {c_factor(256):.4f}\")\n\nprint(\"\\n=== 2. Standard Isolation Forest (Axis-Aligned) vs Extended IF (Oblique) pada Ghost Regions ===\")\nprint(\"Algoritma                | E[h] Norm | E[h] Ghost | Score Norm | Score Ghost | ROC-AUC | PR-AUC\")\nprint(\"-\" * 97)\nfor name, sc, mh in [\n    (\"Standard IF (Axis-Align)\", s_std, h_std),\n    (\"Extended IF (Oblique)\", s_eif, h_eif),\n]:\n    roc = float(roc_auc_score(y_all, sc))\n    pr = float(average_precision_score(y_all, sc))\n    print(\n        f\"{name:24s} | {np.mean(mh[y_all==0]):9.3f} | {np.mean(mh[y_all==1]):10.3f} | \"\n        f\"{np.mean(sc[y_all==0]):10.4f} | {np.mean(sc[y_all==1]):11.4f} | {roc:7.4f} | {pr:6.4f}\"\n    )",
          "expectedOutput": "=== 1. Verifikasi Konstanta BST c(psi) Liu et al. (2008) ===\nc(64) = 7.4720 | c(128) = 8.8584 | c(256) = 10.2448\n\n=== 2. Standard Isolation Forest (Axis-Aligned) vs Extended IF (Oblique) pada Ghost Regions ===\nAlgoritma                | E[h] Norm | E[h] Ghost | Score Norm | Score Ghost | ROC-AUC | PR-AUC\n-------------------------------------------------------------------------------------------------\nStandard IF (Axis-Align) |     9.164 |      6.815 |     0.4910 |      0.5868 |  0.9248 | 0.3418\nExtended IF (Oblique)    |     8.805 |      6.526 |     0.5032 |      0.6001 |  0.9965 | 0.9533",
