          "code": "import numpy as np\nfrom sklearn.metrics import average_precision_score\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import OneClassSVM\n\nrng = np.random.default_rng(2433)\n\n# Bangkitkan 400 titik latih 6D normal + 200 titik uji normal + 20 anomali\nX_tr = rng.normal(0.0, 1.0, size=(400, 6))\nX_te_in = rng.normal(0.0, 1.0, size=(200, 6))\nX_te_an = rng.normal(2.6, 0.9, size=(20, 6))\nX_te = np.vstack([X_te_in, X_te_an])\ny_te = np.array([0] * 200 + [1] * 20)\n\nscaler = StandardScaler().fit(X_tr)\nX_tr_s = scaler.transform(X_tr)\nX_te_s = scaler.transform(X_te)\n\n# 1) Verifikasi Empiris Teorema Scholkopf (2001): frac_train_outliers <= nu <= frac_support_vectors\n#    Gunakan tol=1e-7 agar solver QP memisahkan strict margin outliers (xi_i > 0) dari SV tepat di batas f(x)=0\nprint(\"=== 1. Verifikasi Empiris Teorema Ganda Parameter nu (Scholkopf One-Class SVM) ===\")\nprint(\"nu    | Frac Train Outliers (<= nu) | Frac Support Vectors (>= nu) | Teorema Terpenuhi?\")\nprint(\"-\" * 88)\nfor nu in [0.02, 0.05, 0.15, 0.30]:\n    oc = OneClassSVM(kernel=\"rbf\", nu=nu, gamma=0.05, tol=1e-7).fit(X_tr_s)\n    frac_out = float(np.mean(oc.decision_function(X_tr_s) < -1e-4))\n    frac_sv = float(len(oc.support_) / len(X_tr_s))\n    ok = (frac_out <= nu + 1e-3) and (frac_sv >= nu - 1e-3)\n    print(f\"{nu:5.2f} | {frac_out:27.4f} | {frac_sv:28.4f} | {str(ok)}\")\n\n# 2) Audit Sensitivitas Brutal Hyperparameter gamma pada One-Class SVM (Overfitting Gelembung Sempit!)\nprint(\"\\n=== 2. Audit Jebakan Overfitting gamma pada RBF One-Class SVM (nu=0.05) ===\")\nprint(\"gamma      | Support Vecs (%) | Test Normal FPR | Test Anom Recall | Test PR-AUC | Diagnosis\")\nprint(\"-\" * 96)\nfor g in [0.005, 0.05, 0.167, 1.0, 5.0]:\n    oc = OneClassSVM(kernel=\"rbf\", nu=0.05, gamma=g).fit(X_tr_s)\n    sv_pct = 100.0 * len(oc.support_) / len(X_tr_s)\n    pred = (oc.predict(X_te_s) == -1).astype(int)\n    scores = -oc.decision_function(X_te_s)\n    fpr = 100.0 * float(np.mean(pred[y_te == 0] == 1))\n    rec = 100.0 * float(np.mean(pred[y_te == 1] == 1))\n    pr = float(average_precision_score(y_te, scores))\n    diag = \"Sehat\" if (fpr < 12.0 and rec > 85.0) else (\"Underfit\" if rec < 80.0 else \"OVERFIT GELEMBUNG!\")\n    print(f\"{g:10.3f} | {sv_pct:15.1f}% | {fpr:14.1f}% | {rec:15.1f}% | {pr:11.4f} | {diag}\")",
